def merge_ranges(ranges):
    # Filter out empty ranges and sort
    valid = []
    for r in ranges:
        start, end = r
        if start < end:
            valid.append((start, end))
    valid.sort(key=lambda x: x[0])
    merged = []
    for start, end in valid:
        if not merged:
            merged.append((start, end))
        else:
            last_start, last_end = merged[-1]
            if last_end >= start:  # overlapping or touching
                merged[-1] = (last_start, max(last_end, end))
            else:
                merged.append((start, end))
    return merged

def decode_runs(text):
    if text == "":
        return ""
    i = 0
    n = len(text)
    result = []
    while i < n:
        if not text[i].isdigit():
            raise ValueError()
        cnt_start = i
        while i < n and text[i].isdigit():
            i += 1
        count_str = text[cnt_start:i]
        if count_str == "":
            raise ValueError()
        count = int(count_str)
        if count <= 0:
            raise ValueError()
        if i >= n or not ('a' <= text[i] <= 'z'):
            raise ValueError()
        letter = text[i]
        i += 1
        result.append(letter * count)
    return "".join(result)

from collections import OrderedDict
def lru(capacity, operations):
    cache = OrderedDict()
    results = []
    if capacity == 0:
        for op in operations:
            if op[0] == "get":
                results.append(-1)
        return results
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.pop(key)
            cache[key] = value
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                value = cache.pop(key)
                cache[key] = value
                results.append(value)
            else:
                results.append(-1)
    return results

def flatten(value):
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

import heapq
def shortest(graph, start, end):
    if start == end:
        return 0
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist.get(node, float('inf')):
            continue
        if node == end:
            return d
        for neighbor, weight in graph.get(node, []):
            nd = d + weight
            if nd < dist.get(neighbor, float('inf')):
                dist[neighbor] = nd
                heapq.heappush(heap, (nd, neighbor))
    return None

def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    n = len(values)
    if k > n:
        return []
    from collections import deque
    dq = deque()
    result = []
    for i in range(n):
        # Remove indices outside the current window
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # Remove indices whose corresponding values are less than the current value
        while dq and values[dq[-1]] < values[i]:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

def _copy(obj):
    if isinstance(obj, dict):
        new_dict = {}
        for k, v in obj.items():
            new_dict[k] = _copy(v)
        return new_dict
    elif isinstance(obj, list):
        new_list = []
        for item in obj:
            new_list.append(_copy(item))
        return new_list
    else:
        return obj
def deep_merge(left, right):
    if isinstance(left, dict) and isinstance(right, dict):
        result = {}
        keys = set(left.keys()) | set(right.keys())
        for key in keys:
            l_val = left.get(key)
            r_val = right.get(key)
            if key in left and key in right:
                result[key] = deep_merge(l_val, r_val)
            elif key in right:
                result[key] = _copy(r_val)
            else:
                result[key] = _copy(l_val)
        return result
    else:
        return _copy(right)

from collections import defaultdict, deque
def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    key_queues = defaultdict(deque)
    result = []
    for timestamp, key in events:
        q = key_queues[key]
        # Remove timestamps that are outside the window (<= timestamp - window)
        while q and q[0] <= timestamp - window:
            q.popleft()
        if len(q) < limit:
            q.append(timestamp)
            result.append(True)
        else:
            result.append(False)
    return result

def json_pointer(value, pointer):
    if pointer == "":
        return value
    tokens = pointer.split('/')
    if tokens and tokens[0] == '':
        tokens = tokens[1:]
    current = value
    for token in tokens:
        # Decode JSON Pointer escape sequences: ~1 -> /, ~0 -> ~
        decoded = []
        i = 0
        while i < len(token):
            if token[i] == '~':
                if i + 1 >= len(token):
                    raise ValueError("Malformed escape")
                next_char = token[i + 1]
                if next_char == '1':
                    decoded.append('/')
                    i += 2
                elif next_char == '0':
                    decoded.append('~')
                    i += 2
                else:
                    raise ValueError("Malformed escape")
            else:
                decoded.append(token[i])
                i += 1
        token = ''.join(decoded)
        if isinstance(current, dict):
            if token not in current:
                raise ValueError("Missing path")
            current = current[token]
        elif isinstance(current, list):
            if not token.isdigit():
                raise ValueError("Invalid list index")
            if token != "0" and token.startswith('0'):
                raise ValueError("Invalid list index")
            idx = int(token)
            if idx < 0 or idx >= len(current):
                raise ValueError("Missing path")
            current = current[idx]
        else:
            raise ValueError("Invalid path")
    return current

def stable_unique(values):
    seen = []
    result = []
    for item in values:
        if not any(item == seen_item for seen_item in seen):
            seen.append(item)
            result.append(item)
    return result

def parse_duration(text):
    if not text:
        raise ValueError("Empty input")
    i = 0
    n = len(text)
    total = 0
    last_unit_value = None
    seen_units = set()
    while i < n:
        if not text[i].isdigit():
            raise ValueError("Malformed input")
        num_start = i
        while i < n and text[i].isdigit():
            i += 1
        if num_start == i:
            raise ValueError("Malformed input")
        num = int(text[num_start:i])
        if i >= n or text[i] not in 'hms':
            raise ValueError("Malformed input")
        unit = text[i]
        i += 1
        if unit in seen_units:
            raise ValueError("Repeated unit")
        seen_units.add(unit)
        unit_value = {'h': 3, 'm': 2, 's': 1}[unit]
        if last_unit_value is not None and unit_value > last_unit_value:
            raise ValueError("Units not in descending order")
        last_unit_value = unit_value
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total

def apply_patch(text, edits):
    n = len(text)
    validated = []
    starts = set()
    for edit in edits:
        if not isinstance(edit, tuple) or len(edit) != 3:
            raise ValueError("Each edit must be a tuple (start, end, replacement)")
        start, end, replacement = edit
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Start and end must be integers")
        if start < 0 or end < 0:
            raise ValueError("Start and end must be non-negative")
        if start > end:
            raise ValueError("Start must be less than or equal to end")
        if end > n:
            raise ValueError("End offset out of range")
        if start in starts:
            raise ValueError("Duplicate start offset")
        starts.add(start)
        validated.append((start, end, replacement))
    # Sort edits by start position
    validated.sort(key=lambda x: x[0])
    # Check for overlapping spans
    prev_end = 0
    for start, end, _ in validated:
        if start < prev_end:
            raise ValueError("Overlapping edits")
        prev_end = end
    # Apply the edits
    result_parts = []
    current = 0
    for start, end, replacement in validated:
        result_parts.append(text[current:start])
        result_parts.append(replacement)
        current = end
    result_parts.append(text[current:])
    return ''.join(result_parts)

def expression(text):
    # Tokenize
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            num = int(text[i:j])
            tokens.append(num)
            i = j
        elif ch in '+-*()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("Invalid character")
    # Parsing functions
    pos = 0
    def parse_expression():
        nonlocal pos
        left = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return left
    def parse_term():
        nonlocal pos
        left = parse_factor()
        while pos < len(tokens) and tokens[pos] == '*':
            pos += 1
            right = parse_factor()
            left *= right
        return left
    def parse_factor():
        nonlocal pos
        # Unary plus/minus
        if pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            val = parse_factor()
            if op == '+':
                return val
            else:
                return -val
        # Parentheses
        if pos < len(tokens) and tokens[pos] == '(':
            pos += 1
            val = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return val
        # Number
        if pos < len(tokens) and isinstance(tokens[pos], int):
            val = tokens[pos]
            pos += 1
            return val
        raise ValueError("Invalid syntax")
    try:
        result = parse_expression()
        if pos != len(tokens):
            raise ValueError("Invalid syntax")
        return result
    except ValueError:
        raise

def retry_delays(attempts, initial, cap):
    if attempts < 0 or initial < 0 or cap < 0:
        raise ValueError("Negative arguments are not allowed")
    delays = []
    for i in range(attempts):
        delay = initial * (2 ** i)
        if delay > cap:
            delay = cap
        delays.append(delay)
    return delays

import csv
import io
def csv_records(text):
    if not text or text.strip() == "":
        return []
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)
    if not rows:
        return []
    headers = rows[0]
    # Check for duplicate headers
    if len(headers) != len(set(headers)):
        raise ValueError("Duplicate headers")
    result = []
    for row in rows[1:]:
        if len(row) != len(headers):
            raise ValueError("Row has different number of fields")
        result.append(dict(zip(headers, row)))
    return result

def version_sort(versions):
    def key(v):
        # Split the version string into integer parts
        parts = [int(x) for x in v.split('.')]
        # Remove trailing zero segments
        while parts and parts[-1] == 0:
            parts.pop()
        return tuple(parts)
    # Python's sorted is stable, so ties retain original order
    return sorted(versions, key=key)

def glob_match(pattern, text):
    p_idx = 0
    t_idx = 0
    star_idx = -1
    match_idx = -1
    while t_idx < len(text):
        if p_idx < len(pattern) and (pattern[p_idx] == '?' or pattern[p_idx] == text[t_idx]):
            p_idx += 1
            t_idx += 1
        elif p_idx < len(pattern) and pattern[p_idx] == '*':
            star_idx = p_idx
            match_idx = t_idx
            p_idx += 1
        elif star_idx != -1:
            # backtrack: let * match one more character
            p_idx = star_idx + 1
            match_idx += 1
            t_idx = match_idx
        else:
            return False
    # consume any remaining '*' in the pattern
    while p_idx < len(pattern) and pattern[p_idx] == '*':
        p_idx += 1
    return p_idx == len(pattern)

def memo_cycle(definitions, name):
    memo = {}
    def compute(n, stack):
        if n not in definitions:
            raise ValueError("Missing dependency")
        if n in memo:
            return memo[n]
        val = definitions[n]
        if isinstance(val, int):
            memo[n] = val
            return val
        elif isinstance(val, list):
            if n in stack:
                raise ValueError("Cycle detected")
            stack.add(n)
            total = 0
            for dep in val:
                total += compute(dep, stack)
            stack.remove(n)
            memo[n] = total
            return total
        else:
            raise ValueError("Invalid definition")
    return compute(name, set())
